diff --git a/src/bench/rpc_mempool.cpp b/src/bench/rpc_mempool.cpp
index f319c961a0..97c6d362e7 100644
--- a/src/bench/rpc_mempool.cpp
+++ b/src/bench/rpc_mempool.cpp
@@ -15,6 +15,7 @@
 #include <univalue.h>
 #include <util/check.h>

+#include <cstddef>
 #include <memory>
 #include <vector>

@@ -49,3 +50,38 @@ static void RpcMempool(benchmark::Bench& bench)
 }

 BENCHMARK(RpcMempool);
+
+/** getrawmempool without verbose on chains of CHAIN_LEN small transactions that each spend the previous one.
+ *  The fees are not monotonic along a chain, so that each chain is split into several chunks. */
+static void RpcMempoolTxids(benchmark::Bench& bench)
+{
+    static constexpr int NUM_TXS{10000};
+    static constexpr int CHAIN_LEN{25};
+    static constexpr CAmount FEE_STEP{7919};
+    static constexpr CAmount FEE_RANGE{5000};
+
+    const auto testing_setup = MakeNoLogFileContext<const ChainTestingSetup>(ChainType::MAIN);
+    CTxMemPool& pool = *Assert(testing_setup->m_node.mempool);
+    LOCK2(cs_main, pool.cs);
+
+    CTransactionRef prev;
+    for (int i = 0; i < NUM_TXS; ++i) {
+        CMutableTransaction tx;
+        tx.vin.resize(1);
+        if (i % CHAIN_LEN != 0) tx.vin[0].prevout = COutPoint{prev->GetHash(), 0};
+        tx.vin[0].scriptSig = CScript() << OP_1;
+        tx.vin[0].scriptWitness.stack.push_back({1});
+        tx.vout.resize(1);
+        tx.vout[0].scriptPubKey = CScript() << OP_1 << OP_EQUAL;
+        tx.vout[0].nValue = i;
+        prev = MakeTransactionRef(tx);
+        AddTx(prev, /*fee=*/(i * FEE_STEP) % FEE_RANGE, pool);
+    }
+    Assert(pool.size() == static_cast<size_t>(NUM_TXS));
+
+    bench.run([&] {
+        (void)MempoolToJSON(pool, /*verbose=*/false);
+    });
+}
+
+BENCHMARK(RpcMempoolTxids);
diff --git a/src/test/txgraph_tests.cpp b/src/test/txgraph_tests.cpp
index d86fd7cce4..e821b1831b 100644
--- a/src/test/txgraph_tests.cpp
+++ b/src/test/txgraph_tests.cpp
@@ -432,4 +432,41 @@ BOOST_AUTO_TEST_CASE(txgraph_staging)
     graph->SanityCheck();
 }

+BOOST_AUTO_TEST_CASE(txgraph_main_order)
+{
+    auto graph = MakeTxGraph(50, 1000, HIGH_ACCEPTABLE_COST, PointerComparator);
+
+    // GetMainOrder must list the same transactions as a BlockBuilder that skips nothing.
+    auto check_main_order = [&graph] {
+        std::vector<TxGraph::Ref*> expected;
+        auto builder = graph->GetBlockBuilder();
+        while (auto chunk = builder->GetCurrentChunk()) {
+            expected.insert(expected.end(), chunk->first.begin(), chunk->first.end());
+            builder->Include();
+        }
+        builder.reset();
+        BOOST_CHECK(graph->GetMainOrder() == expected);
+    };
+
+    BOOST_CHECK(graph->GetMainOrder().empty());
+
+    // A chain A -> B -> C -> D whose feerates are split into several chunks, plus two unrelated
+    // transactions, one of them with the same feerate as A.
+    std::vector<TxGraph::Ref> refs;
+    refs.reserve(6);
+    const FeePerWeight feerates[]{{2, 10}, {1, 10}, {2, 10}, {4, 10}, {3, 10}, {2, 10}};
+    for (size_t i = 0; i < std::size(feerates); ++i) {
+        graph->AddTransaction(refs.emplace_back(), feerates[i]);
+        if (i > 0 && i < 4) graph->AddDependency(/*parent=*/refs[i - 1], /*child=*/refs[i]);
+        check_main_order();
+    }
+    BOOST_CHECK_EQUAL(graph->GetMainOrder().size(), refs.size());
+
+    // The order also holds after a removal.
+    graph->RemoveTransaction(refs[4]);
+    check_main_order();
+    BOOST_CHECK_EQUAL(graph->GetMainOrder().size(), refs.size() - 1);
+    graph->SanityCheck();
+}
+
 BOOST_AUTO_TEST_SUITE_END()

